/* Desktop simulation uses the real pinch event path, not a simulated XR session. */
AFRAME.registerComponent('hand-lab',{
 init(){this.active=false;this.listeners=[];this.listen=(el,type,fn,options)=>{el.addEventListener(type,fn,options);this.listeners.push(()=>el.removeEventListener(type,fn,options))};const dock=document.getElementById('spatialDock');this.launch=document.createElement('button');this.launch.hidden=true;this.launch.innerHTML='<span>◌</span>Hand lab';this.launch.onclick=()=>this.active?this.stop():this.start();dock.append(this.launch);this.listen(window,'pointerdown',e=>this.down(e),true);this.listen(window,'pointermove',e=>this.move(e),true);this.listen(window,'pointerup',()=>this.drop(),true);this.listen(window,'pointercancel',()=>this.drop(),true);this.listen(this.el,'enter-vr',()=>this.stop());this.listen(window,'blur',()=>this.stop());this.listen(document,'visibilitychange',()=>{if(document.hidden)this.stop()});this.listen(window,'wheel',e=>{if(!this.active||e.target!==this.el.canvas)return;e.preventDefault();const direction=this.el.camera.getWorldDirection(new AFRAME.THREE.Vector3());this.points.forEach(p=>p.addScaledVector(direction,Math.max(-.15,Math.min(.15,e.deltaY*.001))))},{passive:false})},
 start(){if(this.el.is('vr-mode')){notify('Hand lab is a desktop simulator. Exit VR to use it.');return}const globe=document.getElementById('mapRoot');this.grab=globe.components['bimanual-globe'];this.hands=['globiquestLeftTrackedHand','globiquestRightTrackedHand'].map(id=>document.getElementById(id));if(!this.grab||this.hands.some(h=>!h)){notify('Hand controls are still loading. Try Hand lab again.');return}window.globiquest.closePortal?.();window.globiquest.closeTravel?.();window.globiquest.parachutes?.close();window.globiquest.closeWaterView?.();window.globiquest.setWorkspace('home');document.getElementById('earthRoot').components['globe-rotation']?.release();document.getElementById('earthRoot').components['globe-rotation'].armed=false;this.active=true;this.pinches=[false,false];this.markers=this.hands.map((h,i)=>{const marker=document.createElement('a-sphere');marker.setAttribute('radius',.075);marker.setAttribute('material',`shader:flat; color:${i?'#e8b7cb':'#a6d4cb'}`);const label=document.createElement('a-text');label.setAttribute('value',i?'R':'L');label.setAttribute('align','center');label.setAttribute('color','#26344b');label.setAttribute('width',1.5);label.setAttribute('position','0 0 .08');marker.append(label);this.el.append(marker);return marker});this.bar=document.createElement('div');Object.assign(this.bar.style,{position:'fixed',bottom:'112px',left:'50%',transform:'translateX(-50%)',padding:'10px 14px',borderRadius:'18px',background:'rgba(249,251,254,.96)',border:'1px solid #fff',boxShadow:'0 8px 25px #26374c25',zIndex:'30',font:'12px -apple-system,BlinkMacSystemFont,sans-serif',color:'#26344b',maxWidth:'94vw',display:'flex',alignItems:'center',gap:'8px',flexWrap:'wrap',justifyContent:'center'});const traffic=document.createElement('span');traffic.setAttribute('aria-hidden','true');Object.assign(traffic.style,{display:'inline-flex',gap:'4px',paddingRight:'4px'});['#ee9c9e','#edcd8b','#9ecbb3'].forEach(color=>{const dot=document.createElement('span');Object.assign(dot.style,{width:'6px',height:'6px',borderRadius:'50%',background:color});traffic.append(dot)});this.bar.append(traffic);const title=document.createElement('span');title.textContent='Hand simulator';this.bar.append(title);this.chips=this.hands.map((h,i)=>this.button((i?'R':'L')+' pinch',()=>this.pinch(i,!this.pinches[i])));this.button('Reset',()=>{this.pinches.forEach((p,i)=>this.pinch(i,false));this.grab.reset();this.positionHands();this.pinch(0,true);this.pinch(1,true)});this.button('Close',()=>this.stop());const hint=document.createElement('span');hint.textContent='Drag L/R · Shift-drag moves both · Scroll moves in/out';hint.style.color='#647084';hint.style.flexBasis='100%';hint.style.textAlign='center';this.bar.append(hint);document.body.append(this.bar);this.positionHands();this.pinch(0,true);this.pinch(1,true);this.launch.innerHTML='<span>◌</span>Exit hand lab'},
 button(text,action){const b=document.createElement('button');b.textContent=text;Object.assign(b.style,{border:0,borderRadius:'10px',padding:'8px 12px',background:'#eaf0f5',color:'#27384b',font:'inherit',cursor:'pointer'});b.onclick=action;this.bar.append(b);return b},
 positionHands(){const T=AFRAME.THREE,globe=document.getElementById('mapRoot').object3D,center=globe.getWorldPosition(new T.Vector3()),r=1.18*globe.getWorldScale(new T.Vector3()).x;this.points=[center.clone().add(new T.Vector3(-r*.42,0,r*.7)),center.clone().add(new T.Vector3(r*.42,0,r*.7))]},
 emit(i,type){const hand=this.hands[i],local=hand.object3D.parent.worldToLocal(this.points[i].clone());hand.emit(type,{position:local},false)},
 pinch(i,value){if(!this.active)return;if(value)this.emit(i,'pinchstarted');else this.emit(i,'pinchended');this.pinches[i]=value&&this.grab.grabs.has(this.hands[i]);this.chips[i].style.background=this.pinches[i]?'#c7e5de':'#eaf0f5';this.chips[i].setAttribute('aria-pressed',String(this.pinches[i]))},
 ray(e){const T=AFRAME.THREE,rect=this.el.canvas.getBoundingClientRect(),caster=new T.Raycaster();caster.setFromCamera(new T.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),this.el.camera);return caster.ray},
 down(e){if(!this.active||e.target!==this.el.canvas||e.button!==0)return;const T=AFRAME.THREE,ray=this.ray(e);let best=null;this.points.forEach((p,i)=>{const point=ray.intersectSphere(new T.Sphere(p,.14),new T.Vector3());if(point&&(!best||ray.origin.distanceTo(point)<best.distance))best={i,distance:ray.origin.distanceTo(point)}});if(!best)return;const plane=new T.Plane().setFromNormalAndCoplanarPoint(this.el.camera.getWorldDirection(new T.Vector3()),this.points[best.i]),point=ray.intersectPlane(plane,new T.Vector3());this.dragging={i:best.i,plane,point,starts:this.points.map(p=>p.clone())};this.look=document.getElementById('camera');this.lookEnabled=this.look.getAttribute('look-controls')?.enabled!==false;this.look.setAttribute('look-controls','enabled',false);e.preventDefault();e.stopImmediatePropagation()},
 move(e){if(!this.dragging)return;const T=AFRAME.THREE,d=this.dragging,hit=this.ray(e).intersectPlane(d.plane,new T.Vector3());if(hit){const delta=hit.sub(d.point);if(e.shiftKey)this.points=this.points.map((p,i)=>d.starts[i].clone().add(delta));else this.points[d.i].copy(d.starts[d.i]).add(delta)}e.preventDefault();e.stopImmediatePropagation()},
 drop(){if(!this.dragging)return;this.dragging=null;this.look?.setAttribute('look-controls','enabled',this.lookEnabled)},
 tick(){if(!this.active)return;this.points.forEach((p,i)=>{this.markers[i].object3D.position.copy(p);if(this.pinches[i])this.emit(i,'pinchmoved')})},
 stop(){if(!this.active)return;this.drop();this.pinches.forEach((p,i)=>{if(p)this.emit(i,'pinchended')});this.active=false;this.markers.forEach(m=>m.remove());this.bar.remove();this.launch.innerHTML='<span>◌</span>Hand lab'},
 remove(){this.stop();this.listeners.forEach(fn=>fn());this.launch.remove()}
});
(()=>{const setup=()=>{scene.setAttribute('hand-lab','');window.globiquest.stopHandLab=()=>scene.components['hand-lab']?.stop()};if(scene.hasLoaded)setup();else scene.addEventListener('loaded',setup,{once:true})})();
